(() => {
  const css = `
    :root{--forest:#1e5143;--moss:#718a68;--cream:#f7f2e8;--sand:#e8dfce;--accent:#9f3434;--ink:#18382f;--muted:#5e6c62}
    html[data-theme="dark"]{--cream:#152b25;--sand:#1c3930;--white:#203f35;--line:#3b5a4e;--ink:#f5efe5;--muted:#c5d2c9;--forest:#214f42;--moss:#b6c9a7;--accent:#a63a3b}
    html[data-theme="dark"] .hero{background:radial-gradient(circle at 85% 22%,#315f4e 0,transparent 38%),linear-gradient(125deg,#152b25 30%,#1d3f35 100%)}html[data-theme="dark"] .hero-card{background:linear-gradient(145deg,#214f42,#183a31)}html[data-theme="dark"] .story{background:linear-gradient(135deg,#16382f,#214f42)}html[data-theme="dark"] .event{background:#285846;border:1px solid #3b6e5c}html[data-theme="dark"] .footer{background:#10261f}
    .topbar{background:#8f2f31}.btn-primary{background:#9f3434}.hero-card{background:linear-gradient(145deg,#1e5143,#2e6957)}.story{background:linear-gradient(135deg,#1c473b,#28604f)}.event{padding:0;overflow:hidden;background:var(--white);border:1px solid var(--line);box-shadow:0 12px 28px rgba(24,56,47,.09)}.event img{width:100%;height:190px;object-fit:cover;display:block}.event>div{padding:22px}.event b{font-size:21px}.event p{color:var(--muted);line-height:1.55}.event .event-meta{font-size:13px;color:#9f3434;font-weight:800;letter-spacing:.03em}.event:hover{transform:translateY(-4px);transition:.2s}.theme-toggle{background:var(--white);color:var(--forest)}@media(max-width:800px){.event img{height:210px}}
  `;
  const style=document.createElement('style');style.textContent=css;document.head.append(style);
  const grid=document.querySelector('.event-grid');
  if(grid) grid.innerHTML=[['Salón Darwin','assets/salones/1.jpg','250 personas · 240 m²','Un gran salón para ceremonias religiosas, matrimonios y eventos especiales. Incluye alternativas de oficinas o dependencias, junto con servicio integral de sonido, iluminación, animación, música y montaje.'],['Salón Orgánico','assets/salones/6.jpg','150 personas · 160 m²','Un espacio rodeado de áreas verdes y piscina, con terraza para ceremonias. Ideal para paseos, capacitaciones, matrimonios, retiros, campamentos y celebraciones.'],['Quincho Club House','assets/salones/13.jpg','120 en salón · 40 en quincho','Pensado para grupos y celebraciones al aire libre: salón, quincho, asaderas, áreas verdes, piscina y espacios de entretención.']].map(([name,img,meta,desc])=>`<article class="event"><img loading="lazy" src="${img}" alt="${name}, Fundo El Grillo"><div><div class="event-meta">${meta}</div><b>${name}</b><p>${desc}</p><a class="linkbtn" target="_blank" href="https://wa.me/56961885010?text=${encodeURIComponent('Hola, quiero cotizar '+name+' en Fundo El Grillo')}">Cotizar este salón →</a></div></article>`).join('');
})();
